"""Configure release signing in the Android project generated by Tauri."""

from pathlib import Path


gradle_file = Path("src-tauri/gen/android/app/build.gradle.kts")
source = gradle_file.read_text()
marker = "    buildTypes {\n"
release_marker = '        getByName("release") {\n'
if source.count(marker) != 1 or source.count(release_marker) != 1:
    raise SystemExit("Unexpected Tauri Android Gradle template; update signing setup")

source = source.replace(
    marker,
    """    signingConfigs {
        create("release") {
            storeFile = file(System.getenv("ANDROID_KEYSTORE_FILE"))
            storePassword = System.getenv("ANDROID_KEYSTORE_PASSWORD")
            keyAlias = System.getenv("ANDROID_KEY_ALIAS")
            keyPassword = System.getenv("ANDROID_KEY_PASSWORD")
        }
    }
""" + marker,
    1,
)
source = source.replace(
    release_marker,
    release_marker + '            signingConfig = signingConfigs.getByName("release")\n',
    1,
)
gradle_file.write_text(source)
